func net_gravity_at(world_pos: Vector2) -> Vector2:
    var s = fields.duplicate()
    s.sort_custom(func(a,b): return a["priority"] > b["priority"])
    # The actual order (descending): for each field, the gravity is added to the result; 
    # but if the field has a REPLACE bit, the result is set to the field's gravity. 
    # AND for REPLACE_COMBINE the combine part adds, for COMBINE_REPLACE...
    # Let me actually just implement the combine_replace vs replace_combine and the default gravity
    # based on the likely actual implementation:
    var g = default_gravity * default_gravity_vector
    var r = false
    var r_grav = Vector2.ZERO
    for f in s:
        var rect = Rect2(f["pos"]-f["size"]/2, f["size"])
        if rect.has_point(world_pos):
            var fg = f["gravity_dir"]*f["gravity_val"] if !f["gravity_point"] else (f["pos"]-world_pos).normalized()*f["gravity_val"]
            var m = f["override"]
            if m == Area2D.SPACE_OVERRIDE_DISABLED: continue
            if m == Area2D.SPACE_OVERRIDE_COMBINE:
                if !r: g += fg
            elif m == Area2D.SPACE_OVERRIDE_REPLACE:
                g = fg; r=true
            elif m == Area2D.SPACE_OVERRIDE_REPLACE_COMBINE:
                g = fg + fg; r=true
            elif m == Area2D.SPACE_OVERRIDE_COMBINE_REPLACE:
                g = fg; r=true
    return g
